  search_term: 'Optional text filter on names or titles (at least 2 characters, case-insensitive).',
  dest_dir: 'Local folder to save into. Defaults to the server\'s download folder (CANVAS_DOWNLOAD_DIR).',
  file_path: 'Absolute path of the local file to upload, e.g. "C:/Users/me/essay.pdf".',
  group_id: 'Student group ID (numeric string). Get it from list_my_groups.',
  comment: 'Comment text, visible to your instructor.',
  message: 'Message text. Plain text or simple HTML.',
  body: 'Message body text. Plain text or simple HTML.',
  subject: 'Message subject line.',
  query: 'Search text.',
  start_date: 'Start of the range, as an ISO 8601 date or date-time, e.g. "2026-11-01".',
  end_date: 'End of the range, as an ISO 8601 date or date-time, e.g. "2026-11-30".',
  start_at: 'Start time, ISO 8601, e.g. "2026-11-05T14:00:00-05:00".',
  end_at: 'End time, ISO 8601, e.g. "2026-11-05T15:00:00-05:00".',
  description: 'Optional description text.',
  location_name: 'Optional location name, e.g. "Library room 2".',
  course_ids: 'Course IDs (numeric strings) to include. Get them from list_courses.',
  type: 'Optional enrollment type filter, e.g. "StudentEnrollment".',
  include_concluded: 'If true, also include courses from finished terms.',
  include_assignments: 'If true, include each group\'s assignments in the result.',
  include_completed: 'If true, also include assignments you have already submitted.',
  include_past: 'If true, also include appointment groups whose slots are in the past.',
  bucket: 'Optional filter: "past", "overdue", "undated", "ungraded", "unsubmitted", "upcoming" or "future".',
  only_announcements: 'If true, return announcements instead of discussion topics.',
  max_entries: 'Maximum number of discussion entries to include.',
  max_depth: 'How many folder levels deep to go.',
  namespace: 'Namespace that keeps your data apart from other apps. Defaults to "canvas-mcp".',
  nickname: 'The nickname to show for this course. Only you see it.',
  position: 'Optional position in the bookmark list (1 = first).',
  quiz_submission_id: 'Quiz submission ID from get_my_quiz_submission.',
  assignment_set_id: 'ID of the mastery path option to choose, from get_module_item.',
