const WORDS = { id: 'ID', ids: 'IDs', url: 'URL', ip: 'IP', imscc: 'IMSCC', whoami: 'Who Am I' };

/** Human-readable title for a tool name, e.g. get_tool_launch_url -> "Get Tool Launch URL". */
export function titleFor(name) {
  return name.split('_').map((w) => WORDS[w] || w[0].toUpperCase() + w.slice(1)).join(' ');
}

/** Returns the schema with each parameter's description filled in from the tool's own docs or COMMON_PARAMS. */
export function documentParams(schema, overrides = {}) {
  return Object.fromEntries(Object.entries(schema).map(([key, type]) => {
    const text = overrides[key] || ((!type.description || GENERIC.has(type.description)) && COMMON_PARAMS[key]);
    return [key, text ? type.describe(text) : type];
  }));
}
